/// <summary>
///     The <c>AVABPInfoTableCleaner</c> class is the execution class for deleting BP Info table
/// </summary>
final class AVABPInfoTableCleaner
{
}

Method.Source:
/// <summary>
///     AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVABPInfoTableCleaner locJobClass;

    locJobClass = new AVABPInfoTableCleaner();

    locJobClass.deleteKCS_KBVInfoTmp();
}

/// <summary>
///     AVA <c>deleteKCS_KBVInfoTmp</c> method.
/// </summary>
public void deleteKCS_KBVInfoTmp()
{
    CompanyInfo     locCompanyInfo;

    while select locCompanyInfo
    {
        changecompany(locCompanyInfo.DataArea)
        {
            KCS_KBVInfoTmp  locKCS_KBVInfoTmp;
            ttsBegin;
            delete_from locKCS_KBVInfoTmp;
            ttsCommit;
        }
    }
}
